{%- style -%}
  {{ settings.font_body | font_face: font_display: 'swap' }}
  {{ settings.font_heading | font_face: font_display: 'swap' }}

  :root {
    --color-bg: {{ settings.color_background }};
    --color-surface: {{ settings.color_surface }};
    --color-text: {{ settings.color_text }};
    --color-muted: {{ settings.color_muted }};
    --color-primary: {{ settings.color_primary }};
    --color-primary-text: {{ settings.color_primary_text }};
    --color-accent: {{ settings.color_accent }};
    --color-border: {{ settings.color_border }};

    --font-body: {{ settings.font_body.family }}, {{ settings.font_body.fallback_families }};
    --font-body-weight: {{ settings.font_body.weight }};
    --font-heading: {{ settings.font_heading.family }}, {{ settings.font_heading.fallback_families }};
    --font-heading-weight: {{ settings.font_heading.weight }};
  }
{%- endstyle -%}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-body);
  font-weight: var(--font-body-weight);
  line-height: 1.5;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; }
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: var(--font-heading-weight); line-height: 1.2; margin: 0 0 .5em; }
h1 { font-size: clamp(1.6rem, 3vw, 2.25rem); }
h2 { font-size: clamp(1.3rem, 2.4vw, 1.75rem); }
p { margin: 0 0 1em; }

.skip-link { position: absolute; left: -999px; top: 0; background: var(--color-primary); color: var(--color-primary-text); padding: .5rem 1rem; z-index: 100; }
.skip-link:focus { left: 0; }

.container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 1rem; }
.section { padding: 2.5rem 0; }
.section--surface { background: var(--color-surface); }
.section__title { margin-bottom: 1.25rem; }
.rte > :last-child { margin-bottom: 0; }

/* Botões */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .5rem;
  padding: .7rem 1.25rem; border: 1px solid var(--color-primary); border-radius: 6px;
  background: var(--color-primary); color: var(--color-primary-text);
  font: inherit; font-weight: 600; text-decoration: none; cursor: pointer;
}
.btn:hover { filter: brightness(1.1); }
.btn[disabled], .btn[aria-disabled="true"] { opacity: .5; cursor: not-allowed; filter: none; }
.btn--ghost { background: transparent; color: var(--color-primary); }
.btn--block { width: 100%; }

/* Grade e cards */
.grid { display: grid; gap: 1.25rem; grid-template-columns: repeat(2, 1fr); }
@media (min-width: 750px) { .grid { grid-template-columns: repeat(min(var(--cols, 4), 3), 1fr); } }
@media (min-width: 1000px) { .grid { grid-template-columns: repeat(var(--cols, 4), 1fr); } }
.card { border: 1px solid var(--color-border); border-radius: 8px; overflow: hidden; background: var(--color-bg); display: flex; flex-direction: column; }
.card__media { display: block; aspect-ratio: 1; background: var(--color-surface); }
.card__media img { width: 100%; height: 100%; object-fit: cover; }
.card__body { padding: .9rem; display: flex; flex-direction: column; gap: .35rem; flex: 1; }
.card__title { font-size: 1rem; margin: 0; }
.card__title a { text-decoration: none; }
.card__meta { color: var(--color-muted); font-size: .85rem; }
.badge { display: inline-block; background: var(--color-accent); color: #000; font-size: .75rem; font-weight: 700; padding: .1rem .5rem; border-radius: 4px; }

/* Preço */
.price { display: flex; flex-wrap: wrap; align-items: baseline; gap: .4rem; }
.price__current { font-weight: 700; font-size: 1.1rem; }
.price__old { color: var(--color-muted); }
.price__hint { color: var(--color-muted); flex-basis: 100%; }
.price__gate { color: var(--color-primary); font-size: .9rem; }

/* Formulários */
.field { display: flex; flex-direction: column; gap: .3rem; margin-bottom: 1rem; }
.field label { font-weight: 600; font-size: .9rem; }
input[type="text"], input[type="email"], input[type="tel"], input[type="search"], input[type="number"], select, textarea {
  font: inherit; padding: .6rem .75rem; border: 1px solid var(--color-border); border-radius: 6px; background: var(--color-bg); color: inherit; width: 100%;
}
input:focus-visible, select:focus-visible, textarea:focus-visible, a:focus-visible, button:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }
.qty { max-width: 8rem; }

/* Avisos */
.notice { padding: .8rem 1rem; border-radius: 6px; margin-bottom: 1rem; background: var(--color-surface); border-left: 4px solid var(--color-primary); }
.notice--warn { border-left-color: var(--color-accent); }
.notice--ok { border-left-color: #16a34a; }
.notice--error { border-left-color: #dc2626; }

/* Tabelas (pedido rápido, carrinho, volume) */
.table { width: 100%; border-collapse: collapse; }
.table th, .table td { text-align: left; padding: .6rem .5rem; border-bottom: 1px solid var(--color-border); vertical-align: middle; }
.table th { font-size: .8rem; text-transform: uppercase; letter-spacing: .04em; color: var(--color-muted); }
.table-wrap { overflow-x: auto; }

/* Paginação padrão do Shopify */
.pagination { display: flex; gap: .4rem; justify-content: center; margin: 2rem 0; flex-wrap: wrap; }
.pagination a, .pagination span { padding: .4rem .8rem; border: 1px solid var(--color-border); border-radius: 6px; text-decoration: none; }
.pagination .current { background: var(--color-primary); color: var(--color-primary-text); border-color: var(--color-primary); }

