{%- comment -%}
  Preço consciente de B2B.
  Uso: {% render 'price', product: product %}
       {% render 'price', variant: variant %}

  Dentro de um contexto B2B logado, variant.price já é o preço do catálogo
  da localização atual: aqui só decidimos se mostramos ou não.
{%- endcomment -%}
{%- liquid
  assign target = variant | default: product.selected_or_first_available_variant

  assign hide = false
  if settings.hide_prices_for_guests
    unless customer.b2b?
      assign hide = true
    endunless
  endif
-%}

<div class="price">
  {%- if hide -%}
    <a class="price__gate" href="{{ routes.account_login_url }}">Entre para ver os preços</a>
  {%- else -%}
    {%- if target.compare_at_price > target.price -%}
      <s class="price__old">{{ target.compare_at_price | money }}</s>
    {%- endif -%}
    <span class="price__current">{{ target.price | money }}</span>
    {%- if customer.b2b? and target.quantity_price_breaks.size > 0 -%}
      <small class="price__hint">Desconto por volume disponível</small>
    {%- endif -%}
  {%- endif -%}
</div>

{%- comment -%}
  Faixa no topo: quem está comprando e por qual localização.
  Só aparece para comprador B2B logado.
{%- endcomment -%}
{%- if customer.b2b? -%}
  <div class="b2b-bar">
    <div class="container b2b-bar__row">
      <span>
        Comprando por <strong>{{ customer.current_company.name }}</strong>
        &middot; {{ customer.current_location.name }}
      </span>

      {%- if customer.company_available_locations.size > 1 -%}
        <details class="b2b-bar__switch">
          <summary>Trocar localização</summary>
          <ul>
            {%- for location in customer.company_available_locations -%}
              {%- unless location.current? -%}
                <li><a href="{{ location.url_to_set_as_current }}">{{ location.name }}</a></li>
              {%- endunless -%}
            {%- endfor -%}
          </ul>
        </details>
      {%- endif -%}
    </div>
  </div>
{%- endif -%}

/* Faixa B2B */
.b2b-bar { background: var(--color-primary); color: var(--color-primary-text); font-size: .875rem; }
.b2b-bar__row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding-top: .4rem; padding-bottom: .4rem; flex-wrap: wrap; }
.b2b-bar__switch { position: relative; }
.b2b-bar__switch summary { cursor: pointer; text-decoration: underline; }
.b2b-bar__switch ul { position: absolute; right: 0; z-index: 20; margin: .3rem 0 0; padding: .5rem; list-style: none; background: var(--color-bg); color: var(--color-text); border: 1px solid var(--color-border); border-radius: 6px; min-width: 14rem; }
.b2b-bar__switch li a { display: block; padding: .35rem .5rem; text-decoration: none; }
.b2b-bar__switch li a:hover { background: var(--color-surface); }

