{%- comment -%}
  Card de produto reutilizado na home, coleção e busca.
  Uso: {% render 'product-card', product: product %}
{%- endcomment -%}
{%- assign first_variant = product.selected_or_first_available_variant -%}
{%- assign card_alt = product.featured_image.alt | default: product.title -%}

<article class="card">
  <a class="card__media" href="{{ product.url }}" tabindex="-1" aria-hidden="true">
    {%- if product.featured_image -%}
      {{
        product.featured_image
        | image_url: width: 600
        | image_tag:
          loading: 'lazy',
          widths: '300, 450, 600',
          sizes: '(min-width: 1000px) 25vw, 50vw',
          alt: card_alt
      }}
    {%- endif -%}
  </a>

  <div class="card__body">
    {%- if product.vendor != blank -%}
      <span class="card__meta">{{ product.vendor }}</span>
    {%- endif -%}
    <h3 class="card__title"><a href="{{ product.url }}">{{ product.title }}</a></h3>
    {%- if first_variant.sku != blank -%}
      <span class="card__meta">SKU {{ first_variant.sku }}</span>
    {%- endif -%}

    {% render 'price', product: product %}

    {%- unless product.available -%}
      <span class="badge">Esgotado</span>
    {%- endunless -%}
  </div>
</article>

{%- assign collection = section.settings.collection -%}
<section class="section">
  <div class="container">
    <div class="section__head">
      <h2 class="section__title">{{ section.settings.heading }}</h2>
      {%- if collection != blank -%}
        <a href="{{ collection.url }}">Ver todos</a>
      {%- endif -%}
    </div>

    {%- if collection == blank -%}
      <p class="notice notice--warn">Selecione uma coleção nas configurações da seção.</p>
    {%- else -%}
      <div class="grid" style="--cols: {{ section.settings.columns }}">
        {%- for product in collection.products limit: section.settings.limit -%}
          {% render 'product-card', product: product %}
        {%- endfor -%}
      </div>
    {%- endif -%}
  </div>
</section>

{% schema %}
{
  "name": "Coleção em destaque",
