/* Hero */
.hero { position: relative; background: var(--color-primary); color: var(--color-primary-text); overflow: hidden; }
.hero__bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .35; }
.hero__content { position: relative; padding-top: 4.5rem; padding-bottom: 4.5rem; max-width: 1200px; }
.hero__content > * { max-width: 40rem; }
.hero .btn { background: var(--color-accent); border-color: var(--color-accent); color: #000; }

/* Seções da home */
.section__head { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
.benefit__icon { font-size: 1.75rem; }
.benefit__title { font-size: 1.05rem; margin: .4rem 0 .25rem; }
.benefit__text { color: var(--color-muted); margin: 0; }
.cta { display: flex; justify-content: space-between; align-items: center; gap: 1.5rem; flex-wrap: wrap; }
.cta p { margin: 0; color: var(--color-muted); }

{%- liquid
  assign sort_by = collection.sort_by | default: collection.default_sort_by

  assign has_active_filter = false
  for filter in collection.filters
    if filter.active_values.size > 0
      assign has_active_filter = true
    endif
  endfor
-%}

{%- paginate collection.products by section.settings.per_page -%}
  <div class="container section">
    <h1>{{ collection.title }}</h1>
    {%- if collection.description != blank -%}
      <div class="rte">{{ collection.description }}</div>
    {%- endif -%}

    <form id="collection-filters" class="toolbar" method="get" action="{{ collection.url }}">
      {%- if collection.filters.size > 0 -%}
        <div class="filters">
          {%- for filter in collection.filters -%}
            {%- if filter.type == 'list' or filter.type == 'boolean' -%}
              <details class="filter"{% if filter.active_values.size > 0 %} open{% endif %}>
                <summary>{{ filter.label }}</summary>
                <ul>
                  {%- for value in filter.values -%}
                    <li>
                      <label>
                        <input
                          type="checkbox"
                          name="{{ value.param_name }}"
                          value="{{ value.value }}"
                          {% if value.active %}checked{% endif %}
                          {% if value.count == 0 and value.active == false %}disabled{% endif %}
                        >
                        {{ value.label }} ({{ value.count }})
                      </label>
                    </li>
                  {%- endfor -%}
                </ul>
              </details>
            {%- endif -%}
          {%- endfor -%}
        </div>
      {%- endif -%}

      <div class="toolbar__sort">
        <label for="sort-by">Ordenar</label>
        <select id="sort-by" name="sort_by">
          {%- for option in collection.sort_options -%}
            <option value="{{ option.value }}"{% if option.value == sort_by %} selected{% endif %}>{{ option.name }}</option>
          {%- endfor -%}
        </select>
        <noscript><button class="btn" type="submit">Aplicar</button></noscript>
      </div>
    </form>

    <p class="card__meta">{{ collection.products_count }} produtos{% if has_active_filter %} &middot; <a href="{{ collection.url }}">Limpar filtros</a>{% endif %}</p>

    {%- if collection.products.size == 0 -%}
      <p class="notice">Nenhum produto encontrado com esses filtros.</p>
    {%- else -%}
      <div class="grid" style="--cols: {{ section.settings.columns }}">
        {%- for product in collection.products -%}
          {% render 'product-card', product: product %}
        {%- endfor -%}
      </div>
    {%- endif -%}

    {%- if paginate.pages > 1 -%}
      <nav class="pagination" aria-label="Paginação">{{ paginate | default_pagination }}</nav>
    {%- endif -%}
  </div>
{%- endpaginate -%}

<script src="{{ 'collection.js' | asset_url }}" defer></script>

