/* Coleção */
.toolbar { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; align-items: flex-start; margin: 1rem 0; }
.filters { display: flex; gap: .75rem; flex-wrap: wrap; }
.filter { border: 1px solid var(--color-border); border-radius: 6px; padding: .4rem .75rem; }
