{%- liquid
  assign current = product.selected_or_first_available_variant
  assign form_id = 'product-form-' | append: section.id
  assign qty_id = 'quantity-' | append: section.id
-%}

<div
  class="container section product"
  id="Product-{{ section.id }}"
  data-product-section
  data-section-id="{{ section.id }}"
>
  <div class="product__media">
    {%- for image in product.images -%}
      {%- assign img_loading = forloop.first | ternary: 'eager', 'lazy' -%}
      {{
        image
        | image_url: width: 1000
        | image_tag:
          loading: img_loading,
          widths: '400, 600, 800, 1000',
          sizes: '(min-width: 900px) 50vw, 100vw',
          alt: image.alt
      }}
    {%- endfor -%}
  </div>

  <div class="product__info" data-product-info>
    {%- if product.vendor != blank -%}
      <p class="card__meta">{{ product.vendor }}</p>
    {%- endif -%}
    <h1>{{ product.title }}</h1>
    {%- if current.sku != blank -%}
      <p class="card__meta">SKU {{ current.sku }}</p>
    {%- endif -%}

    {% render 'price', variant: current %}
    {% render 'volume-pricing', variant: current %}

    {%- form 'product', product, id: form_id, class: 'product__form' -%}
      {%- unless product.has_only_default_variant -%}
        {%- for option in product.options_with_values -%}
          <fieldset class="option">
            <legend>{{ option.name }}</legend>
            {%- for value in option.values -%}
              <label class="option__value">
                <input
                  type="radio"
                  name="option-{{ option.position }}"
                  value="{{ value | escape }}"
                  data-option
                  {% if value == option.selected_value %}checked{% endif %}
                >
                <span>{{ value }}</span>
              </label>
            {%- endfor -%}
          </fieldset>
        {%- endfor -%}
      {%- endunless -%}

      <input type="hidden" name="id" value="{{ current.id }}">

      {%- if current.available -%}
        {% render 'quantity-input', variant: current, id: qty_id %}
      {%- endif -%}

      <button class="btn btn--block" type="submit" name="add"{% unless current.available %} disabled{% endunless %}>
        {%- if current.available -%}Adicionar ao carrinho{%- else -%}Indisponível{%- endif -%}
      </button>
    {%- endform -%}

    {%- if product.description != blank -%}
      <div class="rte product__description">{{ product.description }}</div>
    {%- endif -%}
  </div>

  <script type="application/json" data-variants>{{ product.variants | json }}</script>
</div>

<script src="{{ 'product.js' | asset_url }}" defer></script>
<script type="application/ld+json">{{ product | structured_data }}</script>

