// Troca de variante sem recarregar a página.
// Em vez de recalcular preço, faixas de volume e regra de quantidade no
// navegador (e divergir do checkout), pedimos ao servidor o HTML já
// renderizado da seção com a variante escolhida (Section Rendering API).
(() => {
  const root = document.querySelector('[data-product-section]');
  if (!root) return;

  const sectionId = root.dataset.sectionId;
  const variants = JSON.parse(root.querySelector('[data-variants]').textContent);

  root.addEventListener('change', async (event) => {
    if (!event.target.matches('[data-option]')) return;

    const chosen = [...root.querySelectorAll('[data-option]:checked')].map((input) => input.value);
    const variant = variants.find((v) =>
      chosen.every((value, index) => v[`option${index + 1}`] === value)
    );

    const info = root.querySelector('[data-product-info]');
    if (!variant) {
      info.querySelector('button[name="add"]').disabled = true;
      return;
    }

    const url = new URL(window.location.href);
    url.searchParams.set('variant', variant.id);
    window.history.replaceState({}, '', url);

    const response = await fetch(`${url.pathname}?variant=${variant.id}&section_id=${sectionId}`);
    const html = await response.text();
    const fresh = new DOMParser().parseFromString(html, 'text/html').querySelector('[data-product-info]');
    if (fresh) info.replaceWith(fresh);
  });
})();

