// Pedido rápido: valida a regra de quantidade por linha e envia tudo em uma
// única chamada à Cart API (POST /cart/add.js com vários itens).
(() => {
  const root = document.querySelector('[data-quick-order]');
  if (!root) return;

  const inputs = [...root.querySelectorAll('input[data-variant-id]')];
  const totalEl = root.querySelector('[data-total]');
  const errorEl = root.querySelector('[data-quick-error]');
  const button = root.querySelector('[data-add-all]');

  const money = (cents) =>
    (cents / 100).toLocaleString(document.documentElement.lang || 'pt-BR', {
      style: 'currency',
      currency: window.Shopify?.currency?.active || 'BRL',
    });

  const validate = (input) => {
    const qty = Number(input.value) || 0;
    if (qty === 0) return null;
    const min = Number(input.dataset.min);
    const step = Number(input.dataset.increment);
    if (qty < min) return `${input.dataset.label}: quantidade mínima ${min}.`;
    if (qty % step !== 0) return `${input.dataset.label}: use múltiplos de ${step}.`;
    return null;
  };

  const recalc = () => {
    let total = 0;
    inputs.forEach((input) => {
      const qty = Number(input.value) || 0;
      const subtotal = qty * Number(input.dataset.price);
      total += subtotal;
      input.closest('tr').querySelector('[data-subtotal]').textContent = qty ? money(subtotal) : '–';
    });
    totalEl.textContent = money(total);
  };

  const showError = (message) => {
    errorEl.hidden = !message;
    errorEl.textContent = message || '';
  };

  root.addEventListener('input', recalc);

  button?.addEventListener('click', async () => {
    showError('');
    const filled = inputs.filter((input) => Number(input.value) > 0);
    if (filled.length === 0) return showError('Informe ao menos uma quantidade.');

    const problem = filled.map(validate).find(Boolean);
    if (problem) return showError(problem);

    button.disabled = true;
    try {
      const response = await fetch(root.dataset.addUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          items: filled.map((input) => ({
            id: Number(input.dataset.variantId),
            quantity: Number(input.value),
          })),
        }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.description || data.message || 'Não foi possível adicionar.');
      window.location.href = root.dataset.cartUrl;
    } catch (error) {
      showError(error.message);
      button.disabled = false;
    }
  });
})();

